describe('Dynamic Loading - Async Wait', () => {
  beforeEach(() => {
    cy.visit('https://the-internet.herokuapp.com/dynamic_loading/1');
  });

  it('should reveal hidden content after asynchronous loading completes', () => {
    // Verify initial state
    cy.get('[data-testid="finish-element"]').should('be.visible');
    cy.get('[data-testid="finish-element"]').should('contain', 'Hello World!');
    cy.get('[data-testid="loading-indicator"]').should('not.exist');

    // Click the start button to initiate async load
    cy.get('[data-testid="start-button"]').click();

    // Verify loading indicator appears
    cy.get('[data-testid="loading-indicator"]').should('be.visible');
    cy.get('[data-testid="loading-indicator"]').should('contain', 'Loading...');

    // Wait for the loading indicator to disappear (async operation)
    cy.get('[data-testid="loading-indicator"]').should('not.exist');

    // Verify hidden content is now visible and contains expected text
    cy.get('[data-testid="finish-element"]').should('be.visible');
    cy.get('[data-testid="finish-element"]').should('contain', 'Hello World!');
  });

  it('should handle timeout when async operation does not complete', () => {
    // Intercept the async call and delay it beyond the timeout
    cy.intercept('GET', '/api/load-data', (req) => {
      req.reply((res) => {
        res.delay(15000);
        res.send({ statusCode: 200, body: { data: 'Hello World!' } });
      });
    }).as('delayedLoad');

    // Click the start button
    cy.get('[data-testid="start-button"]').click();

    // Verify loading indicator appears
    cy.get('[data-testid="loading-indicator"]').should('be.visible');

    // Wait for the delayed request, which should exceed the 10-second timeout
    cy.wait('@delayedLoad', { timeout: 10000 });

    // Verify the loading indicator is still visible or an error state is shown
    cy.get('[data-testid="loading-indicator"]').should('be.visible');

    // Verify finish element is not visible or still in loading state
    cy.get('[data-testid="finish-element"]').should('not.exist');
  });
});
